import AppKit
import HexpadKit

/// View > Summary… (V19h): document statistics in a copyable dialog.
///
/// The report is generated by the pure, testable ``summaryReport(activeController:)``
/// function so tests can assert its contents without spinning up AppKit UI
/// (the panel is the only untested seam), matching the DebugInfoWindowController
/// pattern.
final class SummaryWindowController {

    /// Builds the full Summary report from the active controller's document.
    ///
    /// `activeController` may be `nil` (no window / headless host); every
    /// session field then degrades to a safe "(none)" value rather than
    /// crashing. The statistics come from the authoritative model
    /// (`DocumentModel`), the line count from the gutter's shared convention
    /// (`GutterGeometry.lineCount`), and the selection from the focused
    /// editor's live selection.
    static func summaryReport(activeController: MainWindowController?) -> String {
        let doc = activeController?.tabStore.selectedDocument
        let text = doc?.text ?? ""
        let selection = activeController?.editorTextView?.selectedRange
            ?? NSRange(location: 0, length: 0)
        let selectionActive = selection.length > 0
        let selectedText = selectionActive ? (text as NSString).substring(with: selection) : ""
        let selectionLineSpan = selectionActive
            ? selectedText.components(separatedBy: "\n").count - 1 + 1
            : 0

        var lines: [String] = []
        lines.append("File: \(doc?.name ?? "(none)")")
        if let path = doc?.filePath?.path {
            lines.append("Path: \(path)")
        } else {
            lines.append("Path: \(doc == nil ? "(none)" : "(untitled)")")
        }
        lines.append("Characters: \(text.count)")
        lines.append("Bytes: \(text.utf8.count)")
        lines.append("Lines: \(doc == nil ? 0 : GutterGeometry.lineCount(in: text))")
        lines.append("Selection: \(selectionActive ? selection.length : 0) chars, \(selectionLineSpan) lines")
        lines.append("Words: \(text.split(whereSeparator: \.isWhitespace).count)")
        lines.append("Encoding: \(doc?.encoding ?? "(none)")")
        lines.append("EOL: \(doc?.eolType ?? "(none)")")
        lines.append("Type: \(doc?.language ?? "(none)")")
        return lines.joined(separator: "\n")
    }

    // MARK: - Dialog

    static func showSummary(activeController: MainWindowController?) {
        presentCopyableAlert(title: "Summary",
                             text: summaryReport(activeController: activeController))
    }

    private static func presentCopyableAlert(title: String, text: String) {
        let alert = NSAlert()
        alert.messageText = title
        alert.informativeText = "Copy this text to see the document's statistics."
        alert.alertStyle = .informational

        let scrollView = NSScrollView(frame: NSRect(x: 0, y: 0, width: 520, height: 300))
        scrollView.hasVerticalScroller = true
        scrollView.hasHorizontalScroller = false
        scrollView.autohidesScrollers = true
        scrollView.borderType = .bezelBorder

        let textView = NSTextView(frame: scrollView.bounds)
        textView.autoresizingMask = [.width, .height]
        textView.isEditable = false
        textView.isSelectable = true
        textView.font = NSFont.monospacedSystemFont(ofSize: 11, weight: .regular)
        textView.string = text
        scrollView.documentView = textView

        alert.accessoryView = scrollView

        alert.addButton(withTitle: "Copy")
        alert.addButton(withTitle: "Close")

        let response = alert.runModal()
        if response == .alertFirstButtonReturn {
            let pasteboard = NSPasteboard.general
            pasteboard.clearContents()
            pasteboard.setString(text, forType: .string)
        }
    }
}
